type Task = { id: string; label: string; done: boolean };

async function saveTask(task: Task): Promise<void> {
  await Promise.resolve(task.id);
}

export function TaskRow({ task }: { task: Task }) @{
  function toggle() {
    saveTask(task);
  }

  <li>
    <button onClick={toggle}>{task.label}</button>
  </li>;
}
